const req = $input.first().json;
let body = req.body ?? {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }

const roster = body.roster || {};
const rosterPlayers = Array.isArray(roster.players) ? roster.players : [];
const matchId = body.match_id || roster.match_id || 'm_unknown';
const jobId = 'job_' + Math.random().toString(36).slice(2, 10);

const heatmap = (pid) =>
  HEATMAP_BASE ? `${HEATMAP_BASE}/${pid}.svg` : `sample-data/heatmaps/${pid}.svg`;

// Re-anchor the fixture onto whichever roster we were handed, so the mock works
// for any club and not only the sample one. This mirrors §7a: identity comes
// from the coach's roster anchor, never from OCR alone.
const players = TRACKS.map((t, i) => {
  const resolved = t.player_id !== null;
  const rp = resolved ? rosterPlayers[i] || null : null;
  const pid = resolved ? (rp ? rp.player_id : t.player_id) : null;
  return {
    player_id: pid,
    track_id: t.track_id,
    // null where the fixture says the shirt number was never legible — keeping
    // that honest is the point of the id_confidence field.
    jersey_number: t.jersey_number === null ? null : (rp ? rp.jersey_number : t.jersey_number),
    id_confidence: t.id_confidence,
    team: t.team,
    heatmap_url: pid ? heatmap(pid) : null,
    distance_m: t.distance_m,
    top_speed_kmh: t.top_speed_kmh,
    avg_position: t.avg_position,
    zone_share: t.zone_share,
    minutes_tracked: t.minutes_tracked,
  };
});

// Team shape over resolved outfield tracks only — same definitions as
// scripts/generate_fixtures.py, so the mock reproduces the frozen fixture.
const outfield = players.filter((p) => p.player_id && p.team !== 'gk');
const xs = outfield.map((p) => p.avg_position.x);
const ys = outfield.map((p) => p.avg_position.y);
const mx = xs.reduce((a, b) => a + b, 0) / xs.length;
const my = ys.reduce((a, b) => a + b, 0) / ys.length;
const r1 = (v) => Math.round(v * 10) / 10;

const result = {
  job_id: jobId,
  status: 'done',
  match_id: matchId,
  clip: { duration_s: 60.0, fps_processed: 5 },
  players,
  team_shape: {
    home: {
      compactness_m: r1(outfield.reduce((a, p, i) => a + Math.hypot(xs[i] - mx, ys[i] - my), 0) / outfield.length),
      width_m: r1(Math.max(...ys) - Math.min(...ys)),
      line_height_m: r1(Math.min(...xs)),
    },
  },
};

const store = $getWorkflowStaticData('global');
store.jobs = store.jobs || {};
store.jobs[jobId] = { polls: 0, created_at: Date.now(), result };

// Don't let the store grow forever across a day of demo runs.
const ids = Object.keys(store.jobs);
if (ids.length > 40) ids.slice(0, ids.length - 40).forEach((k) => delete store.jobs[k]);

return [{ json: { job_id: jobId, status: 'processing', match_id: matchId, tracks: players.length } }];

/* Mock CV service — GET /cv-mock/result?job_id=...   (BUILD_SPEC §6b)
 *
 * Poll 1 -> status "processing".  Poll 2+ -> the full §6b payload.
 *
 * Two escape hatches the main workflow's failure branch is tested against:
 *   ?fail=1     -> status "failed", without having to deactivate this workflow
 *   ?instant=1  -> skip the processing poll
 */
const q = $input.first().json.query || {};
const jobId = q.job_id || '';

if (q.fail === '1' || q.fail === 'true') {
  return [{ json: { job_id: jobId, status: 'failed', error: 'mock: forced failure via ?fail=1' } }];
}

const store = $getWorkflowStaticData('global');
const job = (store.jobs || {})[jobId];

// Static data is written when an execution finishes, so a job we have never
// seen is far more likely to be a lost cache than a bad id. Say so plainly
// rather than inventing a result the main workflow would treat as real.
if (!job) {
  return [{ json: { job_id: jobId, status: 'failed', error: 'mock: unknown job_id (no cached job)' } }];
}

job.polls += 1;

if (job.polls < 2 && q.instant !== '1') {
  return [{ json: { job_id: jobId, status: 'processing', match_id: job.result.match_id, poll: job.polls } }];
}

return [{ json: job.result }];
